local P, R, L, C, U = game:GetService("Players"), game:GetService("RunService"), game:GetService("Players").LocalPlayer, workspace.CurrentCamera, game:GetService("UserInputService") local ai, es, hi, sp, ju, ka, cc, wb = false, false, false, false, false, false, false, false local chL1, chL2, chL3, chL4, chDot local function createCH() local sg = Instance.new("ScreenGui", L.PlayerGui) sg.Name = "CustomCH" chL1 = Instance.new("Frame", sg) chL2 = Instance.new("Frame", sg) chL3 = Instance.new("Frame", sg) chL4 = Instance.new("Frame", sg) chDot = Instance.new("Frame", sg) local function s(f, w, h) f.BackgroundColor3 = Color3.fromRGB(0, 255, 0) f.BorderSizePixel = 0 f.Visible = false f.Size = UDim2.new(0, w, 0, h) f.AnchorPoint = Vector2.new(0.5, 0.5) f.Position = UDim2.new(0.5, 0, 0.5, 0) end s(chL1, 20, 2) s(chL2, 20, 2) s(chL3, 2, 20) s(chL4, 2, 20) s(chDot, 4, 4) end createCH() local function updateCH(v) chL1.Visible = v chL2.Visible = v chL3.Visible = v chL4.Visible = v chDot.Visible = v if v then chL1.Position = UDim2.new(0.5, -15, 0.5, 0) chL2.Position = UDim2.new(0.5, 15, 0.5, 0) chL3.Position = UDim2.new(0.5, 0, 0.5, -15) chL4.Position = UDim2.new(0.5, 0, 0.5, 15) end end local function getTar() local t, sh = nil, math.huge local pFolder = workspace:FindFirstChild("Players") or workspace for _, v in pairs(pFolder:GetChildren()) do if v:IsA("Model") and v:FindFirstChild("HumanoidRootPart") and v:FindFirstChild("Humanoid") and v.Humanoid.Health > 0 and v.Name ~= L.Name then local pos, on = C:WorldToViewportPoint(v.HumanoidRootPart.Position) local d = (Vector2.new(pos.X, pos.Y) - Vector2.new(C.ViewportSize.X/2, C.ViewportSize.Y/2)).Magnitude if d < sh then t = v sh = d end end end return t end U.InputBegan:Connect(function(i, g) if g then return end if wb and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then local target = getTar() if target and target:FindFirstChild("Head") and target:FindFirstChild("Humanoid"